// generated by scripts/gen-api.mjs: a verbatim copy of docs/events.d.ts
// TypeScript types for the run event stream (GET /api/runs/{id}/stream and /events). Hand-written from the backend's emit sites;
// tests/test_event_types.py fails if a kind exists in src/liara_agent/events.py but not here.
// Every event is the envelope { id, ts, kind, data }. Unknown kinds must be ignored (forward compatible).

export type Level = "info" | "warning" | "blocker";
export type Evidence = { file: string; line: number | null; note: string };
export type Params = Record<string, unknown>;

export interface Note { level: Level; message: string; code: string | null; params: Params; evidence: Evidence[] }
export interface QuestionSpec { text: string; code: string | null; params: Params; options: string[] }
export interface EnvVarView { name: string; reference: string | null; has_value: boolean }
export interface AppView {
  name: string; path: string; platform: string; port: number | null; build_command: string | null; start_command: string | null;
  image: string | null; args: string[]; env: EnvVarView[]; disks: { name: string; mount_to: string }[]; role: "web" | "worker"; evidence: Evidence[];
}
export interface DatabaseView { kind: string; id: string; version: string | null; env_var: string | null; evidence: Evidence[] }
export interface StorageView { id: string; permission: string; evidence: Evidence[] }
export interface MailView { domain: string; mode: string; evidence: Evidence[] }
export interface PlanLink { from: string; to: string; to_kind: "database" | "app" | "bucket" | "mail"; env: string[] }  // `from` uses `to` through these variables (names only, never values)
export interface PlanView {
  apps: AppView[]; databases: DatabaseView[]; storage?: StorageView[]; mail?: MailView | null; links: PlanLink[];
  env: { name: string; secret: boolean; source: "user" | "generated" | "database"; evidence: Evidence[] }[];
  questions: (string | QuestionSpec)[]; notes: Note[];
}
export interface CostLine { kind: "app" | "database" | "bucket" | "mail"; name: string; plan: string; tier: string; tier_label: string; hourly_incl_vat: number; monthly_incl_vat: number }
export interface Cost { lines: CostLine[]; total_hourly_incl_vat: number; total_monthly_incl_vat: number }
export interface ReadinessFinding { code: string; level: "info" | "warning"; file: string; line: number | null; params: Params }
export interface FixView { code: string; kind: string; text: string; params: Params; cost_delta_hourly: number }
export interface DiagnosisView { code: string; params: Params; summary: string; evidence: string[]; fixes: FixView[] }
// A request a run would make. `summary` is English; `op` + `params` are stable (create_app, create_database, set_env, upload_source, create_release, resize_app, update_port).
export interface RequestView { method: string; path: string; summary: string; op: string; params: Record<string, string | number> }
/** A thing the agent cannot do for the person. `code` says which (mail_dns | mail_dev_mode | bucket_endpoint_unconfirmed | wordpress_console); `records` are DNS records to add, when there are any. */
export interface FollowUp { code: string; params: Params; records: { type: string; name: string; value: string; status?: string | null; purpose?: string }[] }
export interface Created { apps: string[]; databases: string[]; database_ids: string[]; buckets?: string[]; mail_servers?: string[] }

export type RunEvent =
  | Ev<"run_started", { project: string; dry_run: boolean }>
  | Ev<"phase_started", { phase: Phase }>
  | Ev<"phase_finished", { phase: Phase; manifests?: Record<string, string[]>; hints?: string[]; env_var_names?: string[]; approved?: boolean; ok?: boolean }>
  | Ev<"plan_ready", {
      how: string; how_code: "from_compose" | "investigated_by_agent" | "from_oneclick"; how_params: { file?: string; app?: string }; plan: PlanView; cost: Cost;
      disks: { app: string; name: string; mount_to: string; price: number | null; billing: "unverified" }[];
      readiness: { counts: { warning?: number; info?: number }; findings: ReadinessFinding[] };
      would_send: RequestView[];
      network_id: string | null; network?: { name: string; new: boolean } | null; usage: { calls: number; prompt_tokens: number; completion_tokens: number } | null }>
  | Ev<"run_finished", {
      ok: boolean; dry_run: boolean; created: Created; urls?: Record<string, string>; would_send?: RequestView[];
      stopped?: "blocked" | "cancelled" | "no_plan" | "error"; failed_step?: string; reason?: string; reason_code?: string; reason_params?: Params;
      blockers?: { code: string | null; params: Params; message: string }[]; diagnosis?: DiagnosisView | null;
      fixes?: { code: string; kind: string; params: Params; cost_delta_hourly: number }[]; heal_attempts?: number;
      follow_ups?: FollowUp[] }>  // what the person still has to do: DNS records for mail, a mode switch, the way to Liara's managed WordPress
  | Ev<"agent_message", { text: string }>
  | Ev<"tool_call", { name: "list_dir" | "read_file" | "grep" | "ask_user" | "submit_plan" | string; arguments: string }>
  | Ev<"plan_rejected", { reason: string }>
  | Ev<"plan_updated", { apps: number; databases: number }>
  | Ev<"step_started", { step: string }>
  | Ev<"step_finished", { step: string; state?: StepState | null; dry_run?: boolean }>  // state is absent for database steps; READY = healthy release; DRYRUN only in dry runs
  | Ev<"resource_created", { kind: "app" | "database" | "bucket" | "mail"; permission?: string; mode?: string; id: string; type?: string; platform?: string; plan: string; tier: string; tier_label: string; hourly_price: number; monthly_price: number; dry_run: boolean }>  // prices in toman including VAT; monthly_price is what Liara shows for a month (hourly x 720, rounded to 100)
  | Ev<"resource_updated", { kind: "app"; id: string; plan: string; tier: string; tier_label: string; hourly_price: number; monthly_price: number; previous: { plan: string; tier: string } }>
  | Ev<"build", { step: string; line: string }>
  | Ev<"build_error", { step: string; line: string }>
  | Ev<"warning", { step: string; message: string; code?: string; params?: Params }>
  | Ev<"test_result", { step: string; name: string; ok: boolean; detail: string; url: string }>
  | Ev<"heal_attempt", { step: string; attempt: number; max_attempts: number }>
  | Ev<"diagnosis", DiagnosisView & { app: string }>
  | Ev<"fix_applied", FixResult>
  | Ev<"fix_declined", FixResult>
  | Ev<"patch_ready", { file: string; diff: string }>
  | Ev<"question", { id: string; text: string; options: string[]; code: string | null; params: Params; expires_at?: number | null }>
  | Ev<"answered", { id: string; value: string | null }>
  | Ev<"confirm_request", { id: string; prompt: string; kind: "plan" | "fix" | "patch"; price_delta_hourly: number | null; code: string | null; params: Params; expires_at?: number | null }>
  | Ev<"confirm_response", { id: string; accepted: boolean }>
  | Ev<"secret_request", { id: string; name: string; expires_at?: number | null }>  // expires_at: server clock, unix seconds; an unanswered request is declined then
  | Ev<"secret_provided", { id: string; name: string; provided: boolean }>  // never the value
  | Ev<"request_expired", { id: string; request: string }>;

export type StepState = "READY" | "FAILED" | "UNHEALTHY" | "DRYRUN";
// run_finished: `stopped` is set only when the run ended before or outside a deploy (blocked | cancelled | no_plan | error).
// A diagnosed deploy failure (including a declined fix) has NO `stopped`: ok=false, failed_step, diagnosis and reason_code (the diagnosis code).
export type Phase = "analyze" | "plan" | "confirm" | "deploy";
export interface FixResult { fix: string; note: string; kind: string; params: Params; cost_delta_hourly: number; app: string; code: string }
export interface Ev<K extends string, D> { id: number; ts: number; kind: K; data: D }

export type RunStatus = "running" | "waiting" | "succeeded" | "failed" | "cancelled" | "interrupted";
export interface RunResult {
  ok: boolean | null; stopped: string | null; reason_code: string | null; reason_params: Params; failed_step: string | null;
  diagnosis_code: string | null; created: Created; urls: Record<string, string>; dry_run: boolean | null;
  fixes: { code: string; kind: string; params: Params; cost_delta_hourly: number }[]; heal_attempts: number;  // fixes the agent applied during the run
}
export interface RunRow { id: string; project_id: number; project: string | null; mode: "deploy" | "preview"; status: RunStatus; created_at: number; finished_at: number | null; cleaned_at: number | null; result: RunResult | null }
export interface LiveResource { kind: "app" | "database"; id: string; plan: string; tier: string; tier_label: string; hourly_price: number; monthly_price?: number }
export interface ProjectRow {
  id: number; name: string; source_kind: "zip" | "git"; git_url: string | null; created_at: number;
  last_run: (Omit<RunRow, "project" | "project_id">) | null;
  live: { run_id: string; urls: Record<string, string>; resources: LiveResource[]; hourly_incl_vat: number; monthly_incl_vat: number; free_address_expires_at: number | null } | null;
  runs?: RunRow[];
}
// An open request is an event of kind question / confirm_request / secret_request that has no response yet.
export type OpenRequest = Extract<RunEvent, { kind: "question" | "confirm_request" | "secret_request" }>;
